@app.post("/orders")
def create_order(data: OrderIn, db=Depends(get_db)):
    order = Order(**data.model_dump())
    db.add(order)
    db.flush()                               # order.id assigned
    queue.enqueue(send_confirmation, order.id)
    db.commit()
    return {"id": order.id}

# The worker loads the order by id in a separate database session.

@app.post("/uploads/presign")
def presign(filename: str, user=Depends(current_user)):
    key = f"users/{user.id}/{uuid4()}"
    url = s3.generate_presigned_url(
        "put_object",
        Params={"Bucket": BUCKET, "Key": key},
        ExpiresIn=300,
    )
    return {"url": url, "key": key}

# The browser then PUTs the file bytes directly to url.
